data.script:
function check(value,message){if(!value)throw Error(message);}
const before=editor.getText();
const notes=Draft.query('','all',[]);
for(const title of ['Picker QA: Zulu','Picker QA: Excluded']){
 const target=notes.find(item=>item.title===title);
 check(target,'missing neutral target');
 check(app.currentWindow.openInNewTab(target)===true,'tab not confirmed: '+title);
 check(editor.getText()===before,'source editor changed');
}
context.addSuccessParameter('tabs','two confirmed targets');
console.log('Two target tabs confirmed; source preserved café 🐼');
